import{_ as a,o as e,a as l,b as i}from"./app.DKoEZOcr.js";const n="/ascendc.github.io/pr/5487/assets/mm_quant.DXJy2B7s.png",r="/ascendc.github.io/pr/5487/assets/mm_dequant.BFr9_7d6.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"矩阵乘输出的量化/反量化","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_quant_dequant"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_quant_dequant.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_quant_dequant.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),d={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_quant_dequant.md"};function p(_,t,m,s,u,o){return e(),l("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>矩阵乘输出的量化/反量化</h1><h2 id="功能介绍">功能介绍<a class="header-anchor" href="#功能介绍">​</a></h2><p>对于<a href="#zh-cn_topic_0000002298767893_table1996113269499">特定输入输出数据类型</a>，Matmul支持将计算结果从L0C Buffer（CO1）搬出到Global Memory时，对输出C矩阵元素执行数据量化或反量化操作。</p><ul><li><p>Matmul量化场景：Matmul计算时左矩阵A、右矩阵B为half或bfloat16_t数据类型，输出C矩阵为int8_t数据类型。该场景下，C矩阵的数据从L0C Buffer（CO1）搬出到Global Memory时，会执行量化操作，将最终结果量化为int8_t类型，如下图所示。</p><p><strong>图1</strong> Matmul量化场景示意图<br><img src="'+n+'" alt title="Matmul量化场景示意图"></p></li><li><p>Matmul反量化场景：Matmul计算时左矩阵A、右矩阵B为int8_t或int4b_t数据类型，输出C矩阵为half数据类型，或者左矩阵A、右矩阵B为int8_t数据类型，输出C矩阵为int8_t数据类型。该场景下，C矩阵的数据从L0C Buffer（CO1）搬出到Global Memory时，会执行反量化操作，将最终结果反量化为对应的half类型或int8_t类型，如下图所示。</p><p><strong>图2</strong> Matmul反量化场景示意图<br><img src="'+r+`" alt title="Matmul反量化场景示意图"></p></li></ul><p>Matmul量化/反量化包含两种模式：同一系数的量化/反量化模式、向量的量化/反量化模式，开发者在算子Tiling侧调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetDequantType.html">SetDequantType</a>接口设置量化或反量化模式，这两种模式的具体区别为：</p><ul><li>同一系数的量化/反量化模式（PER_TENSOR模式）：整个C矩阵对应一个量化参数，量化参数的shape为[1]。开发者在算子核函数（Kernel）侧调用接口<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetQuantScalar.html">SetQuantScalar</a>设置量化参数。</li><li>向量的量化/反量化模式（PER_CHANNEL模式）：C矩阵的shape为[m, n]，每个channel维度即C矩阵的每一列，对应一个量化参数，量化参数的shape为[n]。开发者在算子核函数（Kernel）侧调用接口<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetQuantVector.html">SetQuantVector</a>设置量化参数。</li></ul><p><strong>表1</strong> 量化/反量化模式对应的接口配置</p><table><thead><tr><th>模式</th><th>Tiling侧接口</th><th>核函数（Kernel）侧接口</th></tr></thead><tbody><tr><td>同一系数的量化/反量化</td><td>SetDequantType(DequantType::SCALAR)</td><td>SetQuantScalar(gmScalar)</td></tr><tr><td>向量的量化/反量化</td><td>SetDequantType(DequantType::TENSOR)</td><td>SetQuantVector(gmTensor)</td></tr></tbody></table><h2 id="使用场景">使用场景<a class="header-anchor" href="#使用场景">​</a></h2><p>需要对矩阵计算结果进行量化/反量化操作的场景，当前该场景下，Matmul输入输出矩阵支持的数据类型如下表所示。</p><p><strong>表2</strong> Matmul量化/反量化支持的数据类型</p><p><span id="zh-cn_topic_0000002298767893_table1996113269499"></span></p><table><thead><tr><th>A矩阵</th><th>B矩阵</th><th>C矩阵</th><th>支持平台</th></tr></thead><tbody><tr data-filter="950"><td>half</td><td>half</td><td>int8_t</td><td>Ascend 950PR/Ascend 950DT<br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>bfloat16_t</td><td>bfloat16_t</td><td>int8_t</td><td>Ascend 950PR/Ascend 950DT<br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>int8_t</td><td>int8_t</td><td>half</td><td>Ascend 950PR/Ascend 950DT<br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="A3"><td>int4b_t</td><td>int4b_t</td><td>half</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>int8_t</td><td>int8_t</td><td>int8_t</td><td>Ascend 950PR/Ascend 950DT<br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>int8_t</td><td>int8_t</td><td>bfloat16_t</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr data-filter="950"><td>fp8_e4m3fn_t/fp8_e5m2_t</td><td>fp8_e4m3fn_t/fp8_e5m2_t</td><td>fp8_e4m3fn_t/half/bfloat16_t/float</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr><td>hifloat8_t</td><td>hifloat8_t</td><td>hifloat8_t/half/bfloat16_t/float</td><td><span data-filter="950">Ascend 950PR/Ascend 950DT<br><br></span>注意：<br><br>输出为hifloat8_t时，采用Half to Away Round方式量化。<br><br>量化场景的输出为float类型时，该量化模式精度无法达到双万分之一，可以达到双千分之一。如果有双万分之一的精度要求，建议使用AscendDeQuant高阶API。</td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p><a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetQuantScalar.html">SetQuantScalar</a>和<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetQuantVector.html">SetQuantVector</a>接口必须在<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Iterate.html">Iterate</a>或者<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateAll.html">IteratAll</a>接口前调用。</p></li><li><p>在核函数（Kernel）侧与Tiling侧设置的量化/反量化模式需要保持一致：</p><ul><li>核函数（Kernel）侧调用SetQuantScalar接口设置同一系数的量化/反量化模式，对应Tiling侧调用SetDequantType接口配置模式为DequantType::SCALAR。</li><li>核函数（Kernel）侧调用SetQuantVector接口设置向量的量化/反量化模式，对应Tiling侧调用SetDequantType接口配置模式为DequantType::TENSOR。</li></ul></li><li><p>当A、B矩阵为int8_t或int4b_t类型，C矩阵为half时，本节特性的输出结果不支持INF_NAN模式。若结果需要以INF_NAN输出，建议在调用Matmul API时将结果输出到TPosition::VECIN，同时将输出的数据类型设置为int32_t，再基于AIV核使用高阶API <a href="../../../../../api/SIMD-API/adv_api/quantization/AscendDequant.html">AscendDequant</a>将该结果反量化为half类型。</p></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_quant">matmul_quant样例</a>。</p><ul><li><p>Tiling实现</p><p>调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetDequantType.html">SetDequantType</a>接口设置量化或反量化模式，其他实现内容与基础场景相同。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::MatmulApiTiling tiling(ascendcPlatform);
tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT8);
tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT8);
tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT32);
tiling.SetShape(M, N, K);
tiling.SetOrgShape(M, N, K);
tiling.EnableBias(true);
tiling.SetDequantType(DequantType::SCALAR);  // 设置同一系数的量化/反量化模式
// tiling.SetDequantType(DequantType::TENSOR);  // 设置向量的量化/反量化模式
... // 执行其他配置
</code></pre></div></li><li><p>核函数（Kernel）实现</p><p>根据具体量化模式场景，调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetQuantScalar.html">SetQuantScalar</a>或<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetQuantVector.html">SetQuantVector</a>接口设置量化参数。其他实现内容与基础场景相同。</p><ul><li><p>同一系数的量化/反量化模式</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);
float tmp = 0.1;  // 输出gm时会乘以0.1
uint64_t ans = static_cast&lt;uint64_t&gt;(*reinterpret_cast&lt;int32_t*&gt;(&amp;tmp)); // 浮点值量化系数转换为uint64_t类型进行设置
mm.SetQuantScalar(ans);
mm.SetTensorA(gm_a);
mm.SetTensorB(gm_b);
mm.SetBias(gm_bias);
mm.IterateAll(gm_c);
</code></pre></div></li><li><p>向量的量化/反量化模式</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>GlobalTensor gmQuant;
...
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);
mm.SetQuantVector(gmQuant);
mm.SetTensorA(gm_a);
mm.SetTensorB(gm_b);
mm.SetBias(gm_bias);
mm.IterateAll(gm_c);
</code></pre></div></li></ul></li></ul></article></div>`,1)])])}const A=a(d,[["render",p]]);export{h as __pageData,A as default};
